function safeAdd(uint a, uint b) returns (uint c) {
    uint256 c = a + b;
    assert(c >= a);
    return c;
}

function safeSub(uint a, uint b) returns (uint c) {
    assert(b <= a);
    return a - b;
}

function safeMul(uint a, uint b) returns (uint c) {
    uint c = a * b;
    assert(a == 0 || c / a == b);
    return c;
}

function safeDiv(uint a, uint b) returns (uint c) {
    assert(b > 0);
    uint c = a / b;
    assert(a == b * c + a % b);
    return c;
}

contract CryptoTrollsPreSale is CryptoTrolls {
    uint256 public totalTokens = 10000000 * 10**18;
    uint256 public totalPreSaleTokens = 0;
    uint256 public preSaleTokens = 0;
    uint256 public preSaleTokensSold = 0;
    uint256 public preSaleTokensRemaining = 0;
    uint256 public preSaleStartTime = 0;
    uint256 public preSaleEndTime = 0;
    uint256 public preSaleMinPurchase = 0.01 * 10**18;
    uint256 public preSaleMaxPurchase = 100 * 10**18;
    mapping (address => uint256) public preSaleTokens;
    mapping (address => uint256) public preSaleTokensRemaining;
    event PreSaleTokensPurchased(address indexed from, uint256 indexed value, uint256 totalTokens);
    function CryptoTrollsPreSale(
        uint256 initialSupply,
        string tokenName,
        uint8 decimalUnits,
        string tokenSymbol
        ) CryptoTrolls(initialSupply, tokenName, decimalUnits, tokenSymbol) {}
    function setPreSaleStartTime(uint256 startTime) onlyOwner {
        preSaleStartTime = startTime;
    }
    function setPreSaleEndTime(uint256 endTime) onlyOwner {
        preSaleEndTime = endTime;
    }
    function setPreSaleMinPurchase(uint256 minPurchase) onlyOwner {
        preSaleMinPurchase = minPurchase;
    }
    function setPreSaleMaxPurchase(uint256 maxPurchase) onlyOwner {
        preSaleMaxPurchase = maxPurchase;
    }
    function setPreSaleTokens(uint256 tokens) onlyOwner {
        preSaleTokens = tokens;
    }
    function setPreSaleTokensRemaining(uint256 tokens) onlyOwner {
        preSaleTokensRemaining[msg.sender] = tokens;
    }
    function setPreSaleTokensPurchased(address from, uint256 value, uint256 totalTokens) onlyOwner {
        preSaleTokens[from] = value;
        preSaleTokensRemaining[from] = totalTokens - value;
        PreSaleTokensPurchased(from, value, totalTokens);
    }
    function preSaleTokensRemaining(address from) constant returns (uint256 remaining) {
        return preSaleTokensRemaining[from];
    }
    function preSaleTokensPurchased(address from) constant returns (uint256 purchased) {
        return preSaleTokens[from];
    }
    function preSaleTokensPurchased() constant returns (uint256 purchased) {
        return preSaleTokens[msg.sender];
    }
    function preSaleTokensRemaining() constant returns (uint256 remaining) {
        return preSaleTokensRemaining[msg.sender];
    }
    function preSaleTokens() constant returns (uint256 tokens) {
        return preSaleTokens[msg.sender];
    }
    function preSaleTokensRemaining() constant returns (uint256 remaining) {
        return preSaleTokensRemaining[msg.sender];
    }
    function preSaleTokensSold() constant returns (uint256 sold) {
        return preSaleTokensSold;
    }
    function preSaleTokensRemaining() constant returns (uint256 remaining) {
        return preSaleTokensRemaining[msg.sender];
    }
    function preSaleTokens() constant returns (uint256 tokens) {
        return preSaleTokens[msg.sender];
    }
    function preSaleStartTime() constant returns (uint256 startTime) {
        return preSaleStartTime;
    }
    function preSaleEndTime() constant returns (uint256 endTime) {
        return preSaleEndTime;
    }
    function preSaleMinPurchase() constant returns (uint256 minPurchase) {
        return preSaleMinPurchase;
    }
    function preSaleMaxPurchase() constant returns (uint256 maxPurchase) {
        return preSaleMaxPurchase;
    }
    function preSaleTokens() constant returns (uint256 tokens) {
        return preSaleTokens[msg.sender];
    }
    function preSaleTokensRemaining() constant returns (uint256 remaining) {
        return preSaleTokensRemaining[msg.sender];
    }
    function preSaleTokensPurchased() constant returns (uint256 purchased) {
        return preSaleTokens[msg.sender];
    }
    function preSaleTokensPurchased(address from) constant returns (uint256 purchased) {
        return preSaleTokens[from];
    }
    function preSaleTokensRemaining(address from) constant returns (uint256 remaining) {
        return preSaleTokensRemaining[from];
    }
    function preSaleTokensSold() constant returns (uint256 sold) {
        return preSaleTokensSold;
    }
    function preSaleTokensRemaining() constant returns (uint256 remaining) {
        return preSaleTokensRemaining[msg.sender];
    }
    function preSaleTokensPurchased(address from, uint256 value, uint256 totalTokens) onlyOwner {
        preSaleTokens[from] = value;
        preSaleTokensRemaining[from] = totalTokens - value;
        PreSaleTokensPurchased(from, value, totalTokens);
    }
    function preSale() payable {
        if (now < preSaleStartTime) throw;
        if (now > preSaleEndTime) throw;
        if (msg.value < preSaleMinPurchase) throw;
        if (msg.value > preSaleMaxPurchase) throw;
        uint amount = msg.value / buyPrice;                
        if (preSaleTokensRemaining[msg.sender] < amount) throw;               
        if (balanceOf[this] < amount * sellPrice) throw;               
        balanceOf[msg.sender] += amount;                   
        balanceOf[this] -= amount * sellPrice;                         
        preSaleTokensSold += amount;
        preSaleTokensRemaining[msg.sender] -= amount;
        Transfer(this, msg.sender, amount);                   
    }
}
